/* ===== property/js/dashboard/tools/permit-lifecycle-intelligence.js ===== */
(function () {
'use strict';
/* Watchdog proprietary analysis layered on NJ DCA permit records. */
(function(){
  'use strict';var records=Object.create(null);
  function key(r){return String((r&&(r.pams_pin||r.id))||'property').replace(/[^a-z0-9]/gi,'');}
  function clean(v){return String(v==null?'':v).trim();}
  function norm(v){return clean(v).toUpperCase().replace(/[^A-Z0-9]/g,'');}
  function day(v){var d=new Date(v);return isNaN(d)?null:d;}
  function days(a,b){return Math.max(0,Math.round((b-a)/86400000));}
  function lifecycles(rows){
    var groups=Object.create(null),order=[],unmatchable=0;
    (rows||[]).forEach(function(row){var pn=norm(row&&row.permitno),st=clean(row&&row.status).toUpperCase();if(!pn){if(st==='P')unmatchable+=1;return;}if(!groups[pn]){groups[pn]=[];order.push(pn);}groups[pn].push(row);});
    var out=[];
    order.forEach(function(pn){
      var group=groups[pn],issued=group.filter(function(x){return clean(x.status).toUpperCase()==='P';}),certified=group.filter(function(x){return clean(x.status).toUpperCase()==='C'&&clean(x.certdate);});
      if(!issued.length&&!certified.length)return;
      var permitDates=group.map(function(x){return day(x.permitdate);}).filter(Boolean).sort(function(a,b){return a-b;}),certDates=certified.map(function(x){return day(x.certdate);}).filter(Boolean).sort(function(a,b){return a-b;}),rep=certified[certified.length-1]||issued[issued.length-1]||group[0]||{};
      out.push({permit:permitDates[0]||null,certificate:certDates.length?certDates[certDates.length-1]:null,certified:certified.length>0,verification:certified.length===0&&issued.length>0,type:clean(rep.permittype||rep.permittypedesc||'unknown')});
    });
    return{items:out,unmatchable:unmatchable};
  }
  function calc(payload,r){
    var rows=(payload&&payload.rows)||[],now=new Date(),life=lifecycles(rows),items=life.items,candidates=items.filter(function(x){return x.verification;}),closed=items.filter(function(x){return x.certified&&x.permit&&x.certificate;});
    var cycle=closed.map(function(x){return days(x.permit,x.certificate);}).sort(function(a,b){return a-b;}),median=cycle.length?cycle[Math.floor(cycle.length/2)]:null;
    var ages=candidates.map(function(x){return x.permit?days(x.permit,now):0;}),oldest=ages.length?Math.max.apply(null,ages):0,stale=ages.filter(function(x){return x>365;}).length;
    var since=new Date(now);since.setFullYear(now.getFullYear()-2);var recentItems=items.filter(function(x){return x.permit&&x.permit>=since;}),recent=recentItems.length;
    var types={};recentItems.forEach(function(x){types[x.type||'unknown']=1;});
    var intensity=Math.min(100,Math.round(recent*14+Math.max(0,Object.keys(types).length-1)*8));
    var sale=day(r&&(r._lastSaleDate||r.last_sale_date||r.sale_date));var postSale=sale?items.filter(function(x){return x.permit&&x.permit>sale;}).length:null;
    var verify=candidates.length+life.unmatchable;
    var score=Math.min(100,Math.round(Math.min(45,stale*25)+Math.min(25,verify*8)+Math.min(20,oldest/730*20)+Math.min(10,recent/8*10)));
    return{records:rows.length,lifecycles:items.length,verification:verify,certified:closed.length,stale:stale,oldest:oldest,median:median,recent:recent,intensity:intensity,postSale:postSale,score:score,band:score>=65?'High review':score>=35?'Review':'Routine'};
  }
  function render(r,payload){
    var host=document.getElementById('pli-'+key(r));if(!host)return;var v=calc(payload,r);
    // content-architecture: dynamic, this shared tool renders live permit lifecycle metrics and wording from parcel-specific DCA state.
    host.innerHTML='<div class="pci-hero"><div><b>'+v.score+'</b><span>/ 100 lifecycle review</span></div><p><strong>'+v.band+'.</strong> '+(v.verification?v.verification+' permit lifecycle'+(v.verification===1?' needs':'s need')+' certificate or municipal verification in the state feed.':'No permit-number lifecycle currently lacks a certificate date in the matching state feed.')+'</p></div><div class="pci-scenarios"><span><small>Matched lifecycles</small><b>'+v.lifecycles+'</b></span><span><small>Verify municipality</small><b>'+v.verification+'</b></span><span><small>Oldest candidate</small><b>'+(v.verification?v.oldest+' days':'-')+'</b></span><span><small>Median permit → cert.</small><b>'+(v.median==null?'-':v.median+' days')+'</b></span><span><small>Improvement intensity</small><b>'+v.intensity+'/100</b></span><span><small>Post-sale permits</small><b>'+(v.postSale==null?'sale date unavailable':v.postSale)+'</b></span></div><div class="tl-fine">Watchdog groups the live NJ DCA Construction Permit feed by permit number before evaluating certificate state. “Verify municipality” means the matching state lifecycle does not currently show a certificate date, or cannot be safely joined by permit number. It is a preliminary review flag, not proof that work remains legally open; municipal records control.</div>';
  }
  function hydrate(r){var host=document.getElementById('pli-'+key(r));if(!host||typeof ddPermitRecords!=='function')return;ddPermitRecords(r).then(function(p){render(r,p);}).catch(function(){host.innerHTML='<div class="tl-note">The live NJ DCA permit feed could not be checked right now.</div>';});}
  function card(r){records[key(r)]=r;setTimeout(function(){hydrate(r);},0);return toolCard('Permit Lifecycle Intelligence','fa-helmet-safety','<p class="tl-p">Turns raw permit rows into a permit-number lifecycle screen: certificate verification, age, completion time and recent activity.</p><div id="pli-'+key(r)+'"><div class="dd-loading"><span class="pl-spin"></span><div><b>Building permit lifecycle</b><small>Checking live NJ DCA records</small></div></div></div>');}
  Object.assign(window,{permitLifecycleMetrics:calc,toolPermitLifecycle:card});
})();
})();

/* ===== property/js/dashboard/tools/professional-workflows.js ===== */
(function () {
'use strict';
/* Pro+ closing/lending workflows. Calculations are scenarios, never legal/credit conclusions. */
(function(){'use strict';
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function key(r){return String((r&&(r.pams_pin||r.id))||'property').replace(/[^a-z0-9]/gi,'');}
  function money(n){return '$'+Math.round(+n||0).toLocaleString();}
  var rows={};
  function escrowCalc(k){var r=rows[k];if(!r)return;var a=document.getElementById('es-assess-'+k),c=document.getElementById('es-change-'+k),out=document.getElementById('es-out-'+k);if(!a||!out)return;var currentAssess=+r.assessed||0,currentTax=+r.last_year_tax||0,future=+a.value||0,change=(+c.value||0)/100,rate=currentAssess?currentTax/currentAssess:0,scenario=future*rate*(1+change),delta=(scenario-currentTax)/12,reserve=Math.max(0,delta*12),band=delta>500?'high':delta>200?'elevated':delta>50?'watch':'low';out.innerHTML='<div><b>'+money(scenario)+'</b><span>scenario annual tax</span></div><div><b class="'+(delta>0?'dd-warn':'')+'">'+(delta>=0?'+':'')+money(delta)+'</b><span>monthly escrow delta</span></div><div><b>'+money(reserve)+'</b><span>12-month reserve</span></div><div><b>'+band.toUpperCase()+'</b><span>shock band</span></div>';}
  function escrow(r){var k=key(r);rows[k]=r;var mv=(typeof marketValue==='function'&&marketValue(r))||null,assumed=Math.round((mv&&mv.v)||(+r.assessed||0));setTimeout(function(){escrowCalc(k);},0);return '<article class="pw-card"><div class="pw-head"><i class="fas fa-house-circle-exclamation"></i><div><span>PRO+ LENDING</span><h4>Post-closing Escrow Shock</h4><p>Stress-test the tax portion of escrow without pretending a sale automatically causes reassessment in New Jersey.</p></div></div><div class="pw-inputs"><label>Scenario future assessment <input id="es-assess-'+k+'" type="number" value="'+assumed+'" oninput="pwEscrowCalc(\''+k+'\')"></label><label>Tax-rate / levy stress <span><input id="es-change-'+k+'" type="number" value="0" step="1" oninput="pwEscrowCalc(\''+k+'\')">%</span></label></div><div class="pw-results" id="es-out-'+k+'"></div><p class="pw-note">Scenario only. NJ does not generally reassess a property simply because it sold. Change the future assessment to model a revaluation, improvement or added/omitted assessment and adjust the rate stress yourself.</p></article>';}
  var TASKS=[['tax','Property-tax payment status'],['sale','Tax-sale certificate search'],['water','Water / sewer balance'],['charge','Municipal charges / special assessments'],['permit','Open permit / certificate follow-up'],['record','Recorded lien / deed review'],['estate','Inheritance / estate waiver, if applicable'],['mlc','Municipal lien certificate / tax search']];
  function stateKey(k){return'watchdog:municipal-file:'+k;}
  function read(k){try{return JSON.parse(localStorage.getItem(stateKey(k)))||{};}catch(e){return{};}}
  function save(k,id,val){var s=read(k);s[id]=val;localStorage.setItem(stateKey(k),JSON.stringify(s));lienStats(k);}
  function lienStats(k){var s=read(k),vals=TASKS.map(function(t){return s[t[0]]||'unknown';}),done=vals.filter(function(x){return x!=='unknown';}).length,issues=vals.filter(function(x){return x==='issue';}).length,host=document.getElementById('ml-stat-'+k);if(host)host.innerHTML='<b>'+Math.round(done/TASKS.length*100)+'%</b> documented · <b>'+issues+'</b> issue'+(issues===1?'':'s')+' flagged';}
  function lien(r){var k=key(r),s=read(k);setTimeout(function(){lienStats(k);},0);return '<article class="pw-card"><div class="pw-head"><i class="fas fa-stamp"></i><div><span>ATTORNEY / TITLE / LENDER</span><h4>Municipal lien &amp; tax-sale research file</h4><p>A durable checklist for evidence that still lives across municipality, utility, county and title tasks.</p></div></div><div class="pw-stat" id="ml-stat-'+k+'"></div><div class="pw-checklist">'+TASKS.map(function(t){var v=s[t[0]]||'unknown';return '<label><span>'+esc(t[1])+'</span><select onchange="pwLienSave(\''+k+'\',\''+t[0]+'\',this.value)"><option value="unknown"'+(v==='unknown'?' selected':'')+'>Not checked</option><option value="requested"'+(v==='requested'?' selected':'')+'>Requested</option><option value="clear"'+(v==='clear'?' selected':'')+'>Clear / documented</option><option value="issue"'+(v==='issue'?' selected':'')+'>Issue found</option><option value="na"'+(v==='na'?' selected':'')+'>Not applicable</option></select></label>';}).join('')+'</div><p class="pw-note"><b>Important:</b> New Jersey does not provide Watchdog a complete statewide parcel-level municipal-lien/tax-sale feed. This dashboard records your research status; “Clear” is your documented conclusion, not a Watchdog certification.</p></article>';}
  function tool(r){return '<div class="pw-stack">'+escrow(r)+lien(r)+'</div>';}
  Object.assign(window,{toolProfessionalWorkflows:tool,pwEscrowCalc:escrowCalc,pwLienSave:save});
})();
})();

/* ===== property/js/dashboard/tools/tax-trajectory.js ===== */
(function () {
'use strict';
/* Lazy dashboard module: tax-trajectory. */
(function () {
  'use strict';
  // TAX RATE TRAJECTORY
  //
  // Two different things move a property tax bill over time, and they get
  // confused constantly. A revaluation resets the ASSESSMENT to match market
  // value all at once, and the rate falls to compensate (see Revaluation
  // Radar). This is the other one: the town's general tax rate itself, which
  // moves every single year whether or not a reval ever happens, driven by
  // the municipal, school and county budgets it funds.
  //
  // Ten years of that rate are sitting in tax-rates.json, published every
  // year by the Division of Taxation, and mostly unused until now.
  //
  // WHAT THIS DOES NOT DO
  //
  //   It holds the assessment flat and projects the rate forward in a
  //   straight line. That is not a forecast, and budgets do not move in
  //   straight lines. It is the honest answer to "if nothing else changes,
  //   where has this town's rate been heading, and what would that alone do
  //   to this bill." Reassessment Risk and Revaluation Radar cover the
  //   assessment side of the bill separately.
  // ══════════════════════════════════════════════

  function trajectory(r) {
    var hist = rateHistory(r.town, r.county);
    if (!hist || hist.length < 3) return null;

    var first = hist[0], last = hist[hist.length - 1];
    var span = last.year - first.year;
    if (span < 2 || first.rate <= 0) return null;

    // Compound annual growth rate of the rate itself, not the bill, since
    // the bill also depends on the assessment.
    var cagr = Math.pow(last.rate / first.rate, 1 / span) - 1;

    var deltas = [];
    for (var i = 1; i < hist.length; i++) {
      deltas.push((hist[i].rate - hist[i - 1].rate) / hist[i - 1].rate);
    }
    var upYears = deltas.filter(function (d) { return d > 0.001; }).length;
    var downYears = deltas.filter(function (d) { return d < -0.001; }).length;

    // Bands set against New Jersey norms: statewide rate growth has typically
    // run in the low single digits a year. Under 1%/yr reads as flat next to
    // that; over 3.5%/yr is a genuine outlier worth a second look.
    var band = cagr < -0.005 ? 'falling'
             : cagr < 0.010 ? 'stable'
             : cagr < 0.035 ? 'rising'
             : 'fast';

    // Project this property's bill forward holding the assessment flat, to
    // isolate what the rate alone would do.
    var assessed = +r.assessed || null;
    var proj = null;
    if (assessed) {
      var y1 = assessed * (last.rate / 100);
      var y5rate = last.rate * Math.pow(1 + cagr, 5);
      var y5 = assessed * (y5rate / 100);
      proj = { y1: y1, y5: y5, y5rate: y5rate, delta5: y5 - y1 };
    }

    return {
      hist: hist, first: first, last: last, span: span,
      cagr: cagr, band: band, upYears: upYears, downYears: downYears,
      totalYears: hist.length, proj: proj
    };
  }

  var BAND_TEXT = {
    falling: ['Rate has been falling', 'Fewer towns see this than see increases. Usually means new ratables ' +
              'came onto the tax rolls, spreading the same budget over a larger base.'],
    stable:  ['Rate has been roughly flat', 'Budget growth here has stayed close to what new development and ' +
              'normal revenue growth cover on their own.'],
    rising:  ['Rate has been climbing steadily', 'A normal, unremarkable pace of increase for a New Jersey ' +
              'municipality, school district and county combined.'],
    fast:    ['Rate has been climbing fast', 'Meaningfully outpacing the typical town. Worth asking what is ' +
              'driving it, since three separate levies (municipal, school, county) share this one number.']
  };

  function sparkline(hist) {
    var w = 320, h = 64, pad = 6;
    var vals = hist.map(function (x) { return x.rate; });
    var min = Math.min.apply(null, vals), max = Math.max.apply(null, vals);
    var range = (max - min) || 1;
    var step = (w - pad * 2) / (hist.length - 1);
    var pts = hist.map(function (x, i) {
      var px = pad + i * step;
      var py = h - pad - ((x.rate - min) / range) * (h - pad * 2);
      return px.toFixed(1) + ',' + py.toFixed(1);
    }).join(' ');
    var lastX = pad + (hist.length - 1) * step;
    var lastY = h - pad - ((hist[hist.length - 1].rate - min) / range) * (h - pad * 2);

    return '<svg viewBox="0 0 ' + w + ' ' + h + '" style="width:100%;max-width:' + w + 'px;height:' + h +
      'px;display:block" preserveAspectRatio="none">' +
      '<polyline points="' + pts + '" fill="none" stroke="var(--accent-2)" stroke-width="2" ' +
      'stroke-linejoin="round" stroke-linecap="round"/>' +
      '<circle cx="' + lastX.toFixed(1) + '" cy="' + lastY.toFixed(1) + '" r="3.5" fill="var(--accent-2)"/>' +
      '</svg>';
  }

  function toolTaxTrajectory(r) {
    var t = trajectory(r);
    if (!t) return '';
    var b = BAND_TEXT[t.band];
    var pctYr = (t.cagr * 100).toFixed(1);

    return toolCard('Tax rate trajectory', 'fa-chart-line',
      '<p class="tl-p">This tracks ' + esc(r.town || 'this town') + '\u2019s general tax rate itself, published ' +
      'every year by the Division of Taxation, separate from any reassessment or revaluation. It is the rate ' +
      'that funds the municipal, school and county budgets, and it moves every year on its own.</p>' +

      '<div class="rv-head">' +
        '<div class="rv-score ' +
          (t.band === 'fast' ? 'high' : t.band === 'rising' ? 'building' : t.band === 'falling' ? 'minimal' : 'low') +
          '"><b>' + (t.cagr >= 0 ? '+' : '') + pctYr + '%</b><span>per year</span></div>' +
        '<div class="rv-say"><b>' + b[0] + '.</b> ' + b[1] + '</div>' +
      '</div>' +

      '<div class="tt-chart">' + sparkline(t.hist) +
        '<div class="tt-chart-lbl"><span>' + t.first.year + ': ' + t.first.rate.toFixed(3) + '</span>' +
        '<span>' + t.last.year + ': ' + t.last.rate.toFixed(3) + '</span></div>' +
      '</div>' +

      '<p class="tl-p">Over the ' + t.span + ' years on file, the rate rose in ' + t.upYears + ' and fell in ' +
      t.downYears + '.' +
      (t.proj
        ? ' Holding this property\u2019s assessment exactly where it is today and carrying the same pace ' +
          'forward, its bill would move from about <b>' + money(t.proj.y1) + '</b> now to roughly <b>' +
          money(t.proj.y5) + '</b> in five years, a difference of <b>' + money(t.proj.delta5) +
          '</b> from the rate alone.'
        : '') + '</p>' +

      '<div class="tl-fine">Built from the Division of Taxation\u2019s General Tax Rates by County and ' +
      'Municipality, ' + t.first.year + '\u2013' + t.last.year + '. This is a straight line drawn through the ' +
      'past, not a budget forecast, and it holds the assessment fixed on purpose so it isolates the rate. A ' +
      'reassessment or revaluation changes the assessment side of the bill and is covered separately in ' +
      'Reassessment Risk and Revaluation Radar.</div>');
  }

  Object.assign(window, { trajectory, toolTaxTrajectory });
})();
})();

/* ===== property/js/dashboard/tools/real-estate-intelligence.js ===== */
(function () {
'use strict';
/* Ten transparent Watchdog-derived signals for real-estate professionals. */
(function(){
  'use strict';
  function cl(v){return Math.max(0,Math.min(100,Math.round(+v||0)));}
  function avg(parts){var w=0,n=0;parts.forEach(function(p){n+=p[0]*p[1];w+=p[1];});return cl(w?n/w:0);}
  function metrics(r){
    var b=typeof budgetPressureFor==='function'?budgetPressureFor(r):null,rv=typeof revalRadar==='function'?revalRadar(r):null,u=typeof uniFor==='function'?uniFor(r):null,t=typeof trajectory==='function'?trajectory(r):null,s=typeof sr1aFor==='function'?sr1aFor(r):null,c=typeof chapter123==='function'?chapter123(r):null,m=typeof marketValue==='function'?marketValue(r):null;
    var burden=m&&m.v&&r.last_year_tax?cl((+r.last_year_tax/m.v)/.035*100):50,budget=b?cl(b.score):50,reval=rv?cl(rv.score):35,uneven=u?cl(100-(+u.score||50)):50,trend=t?cl(Math.max(0,t.cagr)/.05*100):40,confidence=s?cl((+s.n||0)/120*100):25,appeal=c&&c.testable?cl((c.hasCase?55:20)+Math.max(0,c.over||0)/(+r.assessed||1)*250):15;
    var complete=cl([r.pams_pin,r.address,r.assessed,r.last_year_tax,r.block,r.lot,(r._sqft||r.living_sqft),(r._lastSale||r.watchdog_value),m&&m.v].filter(Boolean).length/9*100);
    var risk=avg([[budget,.23],[reval,.23],[uneven,.18],[trend,.18],[appeal,.18]]);
    return [
      ['watchdog.listing_friction_index','Listing Friction Index',risk,'Higher = more issues likely to complicate a buyer conversation.'],
      ['watchdog.tax_carry_advantage','Tax Carry Advantage',cl(100-burden),'Higher = lighter recurring property-tax burden relative to the model range.'],
      ['watchdog.buyer_objection_radar','Buyer Objection Radar',cl(Math.max(budget,reval,uneven,appeal)),'Highest current tax or assessment objection red flag.'],
      ['watchdog.prelist_readiness_score','Pre-List Readiness Score',avg([[complete,.55],[confidence,.25],[100-risk,.20]]),'Record completeness, evidence confidence and lower surprise risk.'],
      ['watchdog.marketability_drag_index','Marketability Drag Index',avg([[burden,.34],[budget,.23],[reval,.23],[uneven,.20]]),'Recurring tax and municipal conditions that can narrow buyer appeal.'],
      ['watchdog.revaluation_conversation_risk','Revaluation Conversation Risk',avg([[reval,.70],[uneven,.30]]),'How urgently a future assessment reset belongs in the client conversation.'],
      ['watchdog.offer_diligence_priority','Offer Diligence Priority',avg([[risk,.55],[100-complete,.25],[100-confidence,.20]]),'Higher = more source verification before an offer or waiver decision.'],
      ['watchdog.verified_listing_story_strength','Verified Listing Story Strength',avg([[complete,.50],[confidence,.35],[100-uneven,.15]]),'Strength of source-backed facts available to support the listing story.'],
      ['watchdog.assessment_surprise_index','Assessment Surprise Index',avg([[reval,.40],[appeal,.30],[trend,.15],[budget,.15]]),'Likelihood that assessment or tax info becomes a material transaction conversation.'],
      ['watchdog.tax_trend_position','Tax Trend Position',cl(100-trend),'Higher = more stable or restrained recent municipal tax-rate trajectory.']
    ];
  }
  function card(r){var ms=metrics(r);return toolCard('Real Estate Professional Intelligence','fa-house-circle-check','<p class="tl-p">Ten Watchdog-calculated conversation numbers for agents and brokers. Each is built from attributable tax, assessment, market and municipal inputs already in this report; they do not replace MLS facts, inspections or professional diligence.</p><div class="rai-grid">'+ms.map(function(m){return '<a class="dm" data-marker-id="'+m[0]+'" data-marker-value="'+m[2]+' / 100" data-marker-note="'+m[3].replace(/"/g,'&quot;')+'" href="/property/marker?id='+encodeURIComponent(m[0])+'&value='+encodeURIComponent(m[2]+' / 100')+'&note='+encodeURIComponent(m[3])+'"><span><b>'+m[1]+'</b><small>'+m[3]+'</small></span><strong>'+m[2]+'</strong><i class="fas fa-chevron-right"></i></a>';}).join('')+'</div><div class="tl-fine">Watchdog proprietary markers. Scores are decision aids, not predictions of sale price, buyer behavior, legal outcome or appraisal. The marker detail pages publish tier, professional fit, method and source lineage.</div>');}
  Object.assign(window,{realEstateProfessionalMarkers:metrics,toolRealEstateIntelligence:card});
})();
})();

