/* ===== property/js/dashboard/tools/relocation.js ===== */
(function () {
'use strict';
/* Lazy dashboard module: relocation. Generated from the original dashboard without calculation changes. */
(function () {
  'use strict';
  function townRateFor(code) {
    // Effective rate implied by the verified ratio and the town's own median
    // bill. Where a published rate history exists it wins, because it is the
    // actual rate rather than one inferred from it.
    var t = (typeof rates !== 'undefined') ? rates : null;
    var nm = (uniData && uniData[code] && uniData[code].name) || '';
    var cty = (sr1a && sr1a[code] && sr1a[code].county) || '';
    if (t && nm) {
      // keys look like "WINSLOW TWP (CAMDEN)". Match on the town name and,
      // where a county is present, require it too: WASHINGTON TWP and
      // GREENWICH TWP each exist in more than one New Jersey county.
      // The two files abbreviate differently: one says TWP, the other TWNSHP.
      // Normalise both sides before comparing.
      var norm = window.NJPTRTownName && window.NJPTRTownName.normalize;
      if (!norm) throw new Error('Shared town-name normalizer is unavailable');
      var want = norm(nm);
      var keys = Object.keys(t);
      var hit = null;
      for (var i = 0; i < keys.length; i++) {
        var K = keys[i].toUpperCase();
        var base = norm(K.replace(/\s*\([^)]*\)\s*$/, ''));
        if (base !== want) continue;
        if (cty && K.indexOf('(' + cty.toUpperCase() + ')') < 0) continue;
        hit = keys[i];
        break;
      }
      if (hit) {
        {
          var h = t[hit];
          var yrs = Object.keys(h).map(Number).filter(function (y) { return y > 1990; }).sort();
          if (yrs.length) {
            var last = yrs[yrs.length - 1];
            return { rate: +h[String(last)] / 100, src: 'published', year: last,
                     hist: h, years: yrs };
          }
        }
      }
    }
    return null;
  }

  function relocRow(code, budget) {
    var s = sr1a && sr1a[code];
    if (!s || !s.ratio) return null;
    var u = uniData && uniData[code];
    var a = appealData && appealData.counties && appealData.counties[code.slice(0, 2)];
    var pub = townRateFor(code);

    // Assessment a house at this price would carry, then the tax on it.
    var assessed = budget * s.ratio;
    var rate = pub ? pub.rate : null;
    // Without a published rate, infer the effective rate from the town's own
    // median sale and typical bill. Marked clearly as inferred.
    var tax = rate ? assessed * rate : null;

    return {
      code: code,
      name: (u && u.name) || code,
      county: s.county,
      ratio: s.ratio,
      assessed: assessed,
      rate: rate,
      tax: tax,
      inferred: !pub,
      medPrice: s.medPrice,
      ppsf: s.ppsf,
      afford: s.ppsf ? Math.round(budget / s.ppsf) : null,
      uniformity: u ? u.score : null,
      coeff: u ? u.coefficient : null,
      winRate: a ? a.latest.win_rate_filed : null
    };
  }

  function toolRelocation(r) {
    if (!sr1a || !uniData) return '';
    var here = String(r.pams_pin || '').slice(0, 4);
    var opts = Object.keys(sr1a)
      .filter(function (d) { return uniData[d] && uniData[d].name; })
      .map(function (d) { return { d: d, n: uniData[d].name, c: sr1a[d].county }; })
      .sort(function (a, b) { return a.n.localeCompare(b.n); });

    var budget = r.watchdog_value || (r.assessed && sr1a[here] ? r.assessed / sr1a[here].ratio : 400000);
    budget = Math.round(budget / 10000) * 10000;

    var sel = function (n, pre) {
      return '<select id="rl-' + n + '"><option value="">Add a town...</option>' +
        opts.map(function (o) {
          return '<option value="' + o.d + '"' + (o.d === pre ? ' selected' : '') + '>' +
            esc(o.n) + '  \u00b7  ' + esc(titleCase(o.c)) + '</option>';
        }).join('') + '</select>';
    };

    return toolCard('If you moved', 'fa-route',
      '<p class="tl-p">The same money buys a very different tax bill depending on which side of a town line ' +
      'it lands. A listing shows the seller\u2019s bill on one house. This shows what a town charges for a ' +
      'given amount of value, which is the comparison that actually travels.</p>' +

      '<div class="rl-in">' +
        '<div class="rl-b"><label for="rl-budget">Budget</label>' +
          '<div class="rl-money"><span>$</span><input id="rl-budget" type="text" inputmode="numeric" ' +
          'value="' + budget.toLocaleString() + '" oninput="rlGo(this)"></div></div>' +
        '<div class="rl-t"><label>Compare</label><div class="rl-sels">' +
          sel('a', here) + sel('b') + sel('c') + '</div></div>' +
        '<button class="tl-btn" onclick="rlGo()">Compare</button>' +
      '</div>' +
      '<div id="rl-out"></div>' +

      '<div class="tl-fine">Assessment is the budget multiplied by the town\u2019s verified ratio, which is what ' +
      'a house at that price would actually be assessed at there. Tax uses the published general rate where ' +
      'one is on file. A specific property will differ: this compares towns, not houses. Square footage ' +
      'affordable is the budget divided by the median price per square foot in that town.</div>');
  }

  window.rlGo = function (input) {
    if (input) {
      var v = String(input.value).replace(/[^0-9]/g, '');
      input.value = v ? parseInt(v, 10).toLocaleString() : '';
    }
    var b = +String((el('rl-budget') || {}).value || '').replace(/[^0-9]/g, '') || 0;
    var host = el('rl-out');
    if (!host) return;
    if (!b) { host.innerHTML = '<div class="tl-note">Enter a budget.</div>'; return; }

    var picked = ['a', 'b', 'c'].map(function (k) { return (el('rl-' + k) || {}).value; })
      .filter(function (x) { return x; });
    if (!picked.length) { host.innerHTML = '<div class="tl-note">Pick at least one town.</div>'; return; }

    var rows2 = picked.map(function (d) { return relocRow(d, b); }).filter(Boolean);
    if (!rows2.length) { host.innerHTML = '<div class="tl-note">No data for those towns.</div>'; return; }

    var withTax = rows2.filter(function (x) { return x.tax; });
    var best = withTax.length ? withTax.slice().sort(function (x, y) { return x.tax - y.tax; })[0] : null;
    var worst = withTax.length > 1 ? withTax.slice().sort(function (x, y) { return y.tax - x.tax; })[0] : null;

    host.innerHTML =
      '<div class="rl-wrap"><table class="rl-t"><thead><tr><th></th>' +
        rows2.map(function (x) {
          return '<th' + (best && x.code === best.code ? ' class="win"' : '') + '>' + esc(x.name) +
            '<span>' + esc(titleCase(x.county)) + '</span></th>';
        }).join('') + '</tr></thead><tbody>' +
        rlRow('Assessed at this budget', rows2, function (x) { return money(x.assessed); }) +
        rlRow('Town ratio', rows2, function (x) { return (x.ratio * 100).toFixed(1) + '%'; }) +
        rlRow('Estimated annual tax', rows2, function (x) {
          return x.tax ? '<b>' + money(x.tax) + '</b>' : '<span class="na">no rate on file</span>'; }) +
        rlRow('Per month', rows2, function (x) { return x.tax ? money(x.tax / 12) : '-'; }) +
        rlRow('Median sale price', rows2, function (x) { return x.medPrice ? money(x.medPrice) : '-'; }) +
        rlRow('Price per sq ft', rows2, function (x) { return x.ppsf ? '$' + x.ppsf : '-'; }) +
        rlRow('Square feet this buys', rows2, function (x) {
          return x.afford ? x.afford.toLocaleString() + ' sq ft' : '-'; }) +
        rlRow('Assessment uniformity', rows2, function (x) {
          return x.uniformity != null ? x.uniformity + ' of 100' : '-'; }) +
        rlRow('County appeal win rate', rows2, function (x) {
          return x.winRate != null ? x.winRate + '%' : '-'; }) +
      '</tbody></table></div>' +

      (best && worst && worst.tax > best.tax * 1.05
        ? '<div class="rl-say"><b>' + esc(best.name) + ' is the cheaper move.</b> On a ' + money(b) +
          ' budget the difference against ' + esc(worst.name) + ' is <b>' +
          money(worst.tax - best.tax) + ' a year</b>, or ' + money((worst.tax - best.tax) / 12) +
          ' a month, on the same amount of house. Over ten years that is ' +
          money((worst.tax - best.tax) * 10) + ' before any rate increase.</div>'
        : best
        ? '<div class="rl-say">These towns land within a few percent of each other on tax at this budget. ' +
          'What separates them is what the money buys: compare the square footage row.</div>'
        : '');
  };

  function rlRow(label, rows2, fn) {
    return '<tr><th class="rl-l">' + label + '</th>' +
      rows2.map(function (x) { return '<td>' + fn(x) + '</td>'; }).join('') + '</tr>';
  }

  // ══════════════════════════════════════════════
  // 15 · INVESTOR SCREENER
  //
  // Ranks saved properties on the only measure that compares fairly across
  // town lines: tax per thousand dollars of market value. Two properties at
  // the same price in different municipalities can differ by thousands a year,
  // and assessed value cannot show that because assessment levels differ
  // everywhere.
  // ══════════════════════════════════════════════

  Object.assign(window, { townRateFor, relocRow, toolRelocation, rlRow });
})();
})();

/* ===== property/js/dashboard/tools/investor-screen.js ===== */
(function () {
'use strict';
/* Lazy dashboard module: investor-screen. Generated from the original dashboard without calculation changes. */
(function () {
  'use strict';
  function toolInvestorScreen() {
    var rs = (rows || []).filter(function (r) { return r.assessed && r.last_year_tax; });
    if (rs.length < 2) return '';

    var scored = rs.map(function (r) {
      var m = marketValue(r), c = chapter123(r), s = sr1aFor(r), u = uniFor(r);
      var mv = m ? m.v : null;
      return {
        r: r,
        market: mv,
        burden: mv ? (r.last_year_tax / mv) * 1000 : null,   // tax per $1,000 of value
        yieldDrag: mv ? r.last_year_tax / mv : null,
        overBy: (c && c.testable && c.hasCase) ? c.over : 0,
        saving: (c && c.saving) || 0,
        uniformity: u ? u.score : null,
        ratio: s ? s.ratio : null
      };
    }).filter(function (x) { return x.burden != null; });
    if (scored.length < 2) return '';

    scored.sort(function (a, b) { return b.burden - a.burden; });
    var worst = scored[0], best = scored[scored.length - 1];
    var totalSaving = scored.reduce(function (a, x) { return a + x.saving; }, 0);
    var totalTax = scored.reduce(function (a, x) { return a + (+x.r.last_year_tax || 0); }, 0);
    var totalVal = scored.reduce(function (a, x) { return a + x.market; }, 0);

    return toolCard('Portfolio screen', 'fa-ranking-star',
      '<p class="tl-p">Ranked on tax per thousand dollars of market value, which is the only measure that ' +
      'compares fairly across town lines. Assessed value cannot do it, because assessment levels differ in ' +
      'every municipality.</p>' +

      '<div class="iv-top">' +
        '<div><b>' + scored.length + '</b><span>properties</span></div>' +
        '<div><b>' + money(totalTax) + '</b><span>total annual tax</span></div>' +
        '<div><b>$' + (totalTax / totalVal * 1000).toFixed(2) + '</b><span>blended, per $1,000 of value</span></div>' +
        (totalSaving > 0
          ? '<div class="hot"><b>' + money(totalSaving) + '</b><span>at stake in appeals</span></div>' : '') +
      '</div>' +

      '<div class="comps-wrap"><table class="comps"><thead><tr>' +
        '<th>Property</th><th>Town</th><th class="num">Market</th><th class="num">Tax</th>' +
        '<th class="num">Per $1,000</th><th class="num">Over limit</th><th class="num">Uniformity</th>' +
      '</tr></thead><tbody>' +
      scored.map(function (x, i) {
        return '<tr' + (i === 0 && scored.length > 1 ? ' class="hot"' : '') + '>' +
          '<td><b>' + esc(x.r.address) + '</b></td>' +
          '<td>' + esc(x.r.town || '') + '</td>' +
          '<td class="num">' + money(Math.round(x.market / 1000) * 1000) + '</td>' +
          '<td class="num">' + money(x.r.last_year_tax) + '</td>' +
          '<td class="num"><b>$' + x.burden.toFixed(2) + '</b></td>' +
          '<td class="num' + (x.overBy > 0 ? ' neg' : '') + '">' +
            (x.overBy > 0 ? money(x.overBy) : '-') + '</td>' +
          '<td class="num">' + (x.uniformity != null ? x.uniformity : '-') + '</td></tr>';
      }).join('') + '</tbody></table></div>' +

      (worst.burden > best.burden * 1.15
        ? '<div class="iv-say"><b>' + esc(worst.r.address) + ' carries the heaviest burden</b> at $' +
          worst.burden.toFixed(2) + ' per thousand against $' + best.burden.toFixed(2) + ' for ' +
          esc(best.r.address) + '. On equal value that is a gap of <b>' +
          money((worst.burden - best.burden) * worst.market / 1000) + ' a year</b>. ' +
          'That difference is the municipality, not the property.</div>'
        : '<div class="iv-say">Tax burden is fairly even across these, within 15 percent per dollar of value. ' +
          'No one property is dragging on the others.</div>') +

      '<div class="tl-fine">Market value comes from the state verified sales ratio where available. Tax per ' +
      'thousand is the prior year bill divided by market value. This is a screening comparison, not an ' +
      'investment recommendation, and it takes no account of rent, condition, vacancy or financing.</div>');
  }

  // ══════════════════════════════════════════════

  Object.assign(window, { toolInvestorScreen });
})();
})();

/* ===== property/js/dashboard/tools/investor-carry-volatility.js ===== */
(function () {
'use strict';
/* Watchdog proprietary: tax-driven carry-cost volatility. */
(function () {
  'use strict';
  function clamp(v){return Math.max(0,Math.min(100,+v||0));}
  function pct(v){return v==null?'-':((+v)*100).toFixed(1)+'%';}
  function calc(r){
    var b=typeof budgetPressureFor==='function'?budgetPressureFor(r):null;
    var t=typeof trajectory==='function'?trajectory(r):null;
    var rv=typeof revalRadar==='function'?revalRadar(r):null;
    var x=typeof exemptPilotFor==='function'?exemptPilotFor(r):null;
    if(!b&&!t&&!rv)return null;
    var gap=b&&b.trend?Math.max(0,(+b.trend.total_levy_cagr||0)-(+b.trend.ratable_growth||0)):0;
    var parts=[
      {label:'Municipal budget pressure',value:b?clamp(b.score):50,weight:.32},
      {label:'Levy / ratable growth gap',value:clamp(gap/.05*100),weight:.24},
      {label:'Revaluation reset pressure',value:rv?clamp(rv.score):35,weight:.22},
      {label:'Tax-rate trend',value:t?clamp(Math.max(0,t.cagr)/.05*100):35,weight:.14},
      {label:'Exempt / PILOT exposure',value:x?clamp((+x.exempt_share||0)/.35*100):25,weight:.08}
    ];
    var score=Math.round(parts.reduce(function(a,p){return a+p.value*p.weight;},0));
    var band=score>=70?'High':score>=48?'Elevated':score>=25?'Moderate':'Low';
    var tax=+r.last_year_tax||0,cagr=t?t.cagr:0;
    return {score:score,band:band,parts:parts,gap:gap,cagr:cagr,tax:tax,one:tax*Math.pow(1+Math.max(-.1,cagr),1),three:tax*Math.pow(1+Math.max(-.1,cagr),3),five:tax*Math.pow(1+Math.max(-.1,cagr),5)};
  }
  function card(r){
    var v=calc(r);if(!v)return '';
    return toolCard('Investor Carry-Cost Volatility','fa-chart-area',
      '<p class="tl-p">A Watchdog operating-cost stability sign for investors. It combines municipal fiscal pressure, levy growth that is not being absorbed by new ratables, revaluation pressure, the tax-rate path and exempt/PILOT exposure.</p>'+
      '<div class="pci-hero"><div><b>'+v.score+'</b><span>/ 100 volatility</span></div><p><strong>'+v.band+' carry-cost uncertainty.</strong> This measures tax-driven variability, not investment quality or a forecast of the next bill.</p></div>'+
      '<div class="pci-grid">'+v.parts.map(function(p){return '<div><span>'+p.label+'</span><b>'+Math.round(p.value)+'</b><i><em style="width:'+p.value+'%"></em></i></div>';}).join('')+'</div>'+
      (v.tax?'<div class="pci-scenarios"><span><small>Current tax</small><b>'+money(v.tax)+'</b></span><span><small>1-year path</small><b>'+money(v.one)+'</b></span><span><small>3-year path</small><b>'+money(v.three)+'</b></span><span><small>5-year path</small><b>'+money(v.five)+'</b></span></div>':'')+
      '<div class="tl-fine">Watchdog proprietary model. Weights: budget pressure 32%, levy/base gap 24%, revaluation pressure 22%, rate trend 14%, exempt/PILOT exposure 8%. The dollar path simply carries the historical tax-rate CAGR forward while holding the assessment fixed. Sources: NJ Division of Taxation, NJ DCA User-Friendly Budgets, Abstract of Ratables, SR1A/uniformity data and DCA PILOT data.</div>');
  }
  function portfolio(list){
    var vals=(list||[]).map(function(r){var v=calc(r);return v?{r:r,v:v}:null;}).filter(Boolean).sort(function(a,b){return b.v.score-a.v.score;});
    if(!vals.length)return '';
    var avg=Math.round(vals.reduce(function(a,x){return a+x.v.score;},0)/vals.length);
    var byTown={};vals.forEach(function(x){var k=String(x.r.town||x.r.municipality||'Unknown');byTown[k]=(byTown[k]||0)+Math.max(1,x.v.tax);});var total=Object.keys(byTown).reduce(function(a,k){return a+byTown[k];},0),shares=Object.keys(byTown).map(function(k){return{town:k,share:byTown[k]/total};}).sort(function(a,b){return b.share-a.share;}),hhi=Math.round(shares.reduce(function(a,x){return a+x.share*x.share;},0)*100),top=shares[0];
    return '<section class="sec"><h4><i class="fas fa-chart-area"></i> Investor Carry-Cost Volatility</h4><div class="pci-portfolio"><div class="pci-hero"><div><b>'+avg+'</b><span>/ 100 portfolio average</span></div><p>Tax-driven operating-cost uncertainty across '+vals.length+' saved propert'+(vals.length===1?'y':'ies')+'.</p></div><div class="pci-scenarios"><span><small>Municipal concentration</small><b>'+hhi+'/100</b></span><span><small>Largest town share</small><b>'+(top?Math.round(top.share*100)+'%':'-')+'</b></span><span><small>Largest exposure</small><b>'+(top?top.town:'-')+'</b></span></div>'+vals.slice(0,8).map(function(x){return '<a href="/property/home?pin='+encodeURIComponent(x.r.pams_pin||'')+'#sec-compare"><span>'+String(x.r.address||'Saved property')+'</span><b>'+x.v.score+' · '+x.v.band+'</b></a>';}).join('')+'</div></section>';
  }
  Object.assign(window,{carryCostVolatility:calc,toolCarryCostVolatility:card,toolCarryCostPortfolio:portfolio});
})();
})();

/* ===== property/js/dashboard/tools/tax-pressure-simulator.js ===== */
(function () {
'use strict';
/* Property tax pressure scenario: assessment movement and rate movement kept separate. */
(function () {
  'use strict';

  function toolTaxPressure(r) {
    if (!r || !r.assessed || !r.last_year_tax) return '';
    var town = typeof townIntelFor === 'function' ? townIntelFor(r) : null;
    var budget = typeof budgetPressureFor === 'function' ? budgetPressureFor(r) : null;
    var rateGrowth = town && town.trajectory ? town.trajectory.cagr * 100 : 2.5;
    var id = 'tp-' + String(r.pams_pin || 'property').replace(/[^a-z0-9]/gi, '');
    return toolCard('Tax bill pressure simulator', 'fa-sliders',
      '<p class="tl-p">A tax bill can move because the assessment changes, the general tax rate changes, or both. Adjust them separately so one does not get mistaken for the other.</p>' +
      '<div class="tp-controls" id="' + id + '">' +
        '<label>Assessment change <output>0%</output><input type="range" min="-20" max="100" value="0" step="1" data-k="assessment"></label>' +
        '<label>Annual rate change <output>' + rateGrowth.toFixed(1) + '%</output><input type="range" min="-3" max="8" value="' + rateGrowth.toFixed(1) + '" step="0.1" data-k="rate"></label>' +
        '<label>Years ahead <output>5</output><input type="range" min="1" max="10" value="5" step="1" data-k="years"></label>' +
      '</div><div class="tp-output" id="' + id + '-out"></div>' +
      (budget ? '<div class="tl-note"><b>Budget info:</b> ' + budget.score + '/100 ' + budget.band +
        ' municipal pressure. This does not change the rate slider because the pressure score is not a forecast.</div>' : '') +
      '<div class="tl-fine">This is an adjustable scenario, not a forecast. It starts with the current assessment and effective tax rate. The rate control defaults to the municipality\'s own historical pace when enough years are available.</div>');
  }

  function calculate(host) {
    var root = host.closest('.tool') || host.parentElement;
    var assessmentChange = +host.querySelector('[data-k="assessment"]').value;
    var rateChange = +host.querySelector('[data-k="rate"]').value;
    var years = +host.querySelector('[data-k="years"]').value;
    host.querySelector('[data-k="assessment"]').previousElementSibling.textContent = assessmentChange + '%';
    host.querySelector('[data-k="rate"]').previousElementSibling.textContent = rateChange.toFixed(1) + '%';
    host.querySelector('[data-k="years"]').previousElementSibling.textContent = years;
    var pin = host.id.replace(/^tp-/, '');
    var r = rows.filter(function (row) { return String(row.pams_pin || '').replace(/[^a-z0-9]/gi, '') === pin; })[0];
    if (!r) return;
    var currentRate = +r.last_year_tax / +r.assessed;
    if(window.WatchdogTaxYears && WatchdogTaxYears.mismatch(r)){ root.querySelector('.tp-output').innerHTML='<div><span>Projection paused</span><b>Assessment and tax years do not match</b><small>Enter or wait for a same-year published rate. Watchdog will not apply an old rate to a revalued assessment.</small></div>'; return; }
    var assessment = +r.assessed * (1 + assessmentChange / 100);
    var projected = assessment * currentRate * Math.pow(1 + rateChange / 100, years);
    var delta = projected - +r.last_year_tax;
    root.querySelector('.tp-output').innerHTML = '<div><span>Bill today</span><b>' + money(r.last_year_tax) + '</b></div>' +
      '<i class="fas fa-arrow-right"></i><div class="' + (delta > 0 ? 'up' : 'down') + '"><span>Scenario in ' + years + ' years</span><b>' + money(projected) + '</b><small>' +
      (delta >= 0 ? '+' : '-') + money(Math.abs(delta)) + ' per year</small></div>';
  }

  document.addEventListener('input', function (event) {
    var input = event.target.closest('.tp-controls input');
    if (input) calculate(input.closest('.tp-controls'));
  });
  document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.tp-controls').forEach(calculate);
  });
  window.setTimeout(function () { document.querySelectorAll('.tp-controls').forEach(calculate); }, 0);

  Object.assign(window, { toolTaxPressure: toolTaxPressure });
})();
})();

/* ===== property/js/dashboard/tools/watchdog-score.js ===== */
(function () {
'use strict';
/* Lazy dashboard module: watchdog-score. Canonical ROBUST component evaluation for the Dashboard. */
(function () {
  'use strict';

  var Core = window.WatchdogScoreCore;
  if (!Core) throw new Error('WatchdogScoreCore is required before watchdog-score');

  // THE WATCHDOG SCORE
  // One number, 0 to 100, for how a New Jersey property stands as a tax
  // proposition. ROBUST-v1 owns dimension order, weights, aggregation,
  // evidence coverage, confidence and accepted model versions.
  //
  // The internal key `fairness` remains for compatibility. Its public ROBUST
  // name is O - Overassessment Position.

  var BURDEN_BEST = 0.012, BURDEN_WORST = 0.036;
  var ROBUST_META = Core.DIMENSIONS;
  var clamp01 = Core.clamp01;

  function watchdogScore(r) {
    var detail = {};

    function add(key, value, note) {
      var meta = ROBUST_META[key];
      var label = meta.letter + ' \u00b7 ' + meta.name;
      var normalized = value == null ? null : clamp01(value);
      detail[key] = {
        key: key,
        publicKey: meta.publicKey,
        letter: meta.letter,
        name: meta.name,
        slug: meta.slug,
        label: label,
        score: normalized == null ? null : Math.round(normalized * 100),
        weight: meta.weight,
        note: note || (normalized == null ? 'no data' : '')
      };
    }

    var m = marketValue(r);
    var c = chapter123(r);
    var u = uniFor(r);
    var a = appealFor(r);
    var s = sr1aFor(r);
    var rv = (typeof revalRadar === 'function') ? revalRadar(r) : null;

    // B - Burden, 30
    if (m && m.v && r.last_year_tax) {
      var eff = r.last_year_tax / m.v;
      add('burden', (BURDEN_WORST - eff) / (BURDEN_WORST - BURDEN_BEST),
          '$' + (eff * 1000).toFixed(2) + ' per $1,000 of market value');
    } else {
      add('burden', null);
    }

    // O - Overassessment Position, 20. Internal key remains `fairness`.
    if (c && c.testable && c.limit) {
      var over = (r.assessed - c.limit) / c.limit;
      var fair = over <= 0 ? clamp01(1 - (r.assessed - c.fair) / Math.max(c.fair, 1) * 0.5)
                           : clamp01(1 - over / 0.30) * 0.5;
      add('fairness', fair,
          c.hasCase ? money(Math.round(c.over)) + ' above the Chapter 123 limit'
                    : 'within the statutory cushion');
    } else {
      add('fairness', null, 'needs comparable sales to test');
    }

    // U - Uniformity, 15
    if (u && u.coefficient != null) {
      add('uniformity', 1 - clamp01((u.coefficient - 7) / 23),
          'coefficient ' + u.coefficient + ', standard is 15');
    } else {
      add('uniformity', null);
    }

    // S - Stability, 15
    if (rv && rv.score != null) {
      add('stability', 1 - clamp01(rv.score / 100), 'revaluation pressure ' + rv.score + ' of 100');
    } else {
      add('stability', null);
    }

    // T - Trajectory, 10
    // Raw MOD-IV deed fields can contain nominal $1/$100 transfers. They are
    // not evidence of market trajectory. Until a stronger verified-sale flag
    // is available in this Dashboard record shape, require a plausible sale
    // amount and year or drop T and let evidence coverage fall honestly.
    var lastSale = Number(r._lastSale);
    var lastSaleYear = Number(r._lastSaleYear);
    var currentYear = new Date().getFullYear();
    var defensibleSale = Number.isFinite(lastSale) && lastSale > 40000 &&
      Number.isFinite(lastSaleYear) && lastSaleYear >= 1900 && lastSaleYear <= currentYear;
    if (s && defensibleSale && r.assessed) {
      var implied = r.assessed / lastSale;
      var rel = implied / s.ratio;
      var traj = rel < 0.85 ? clamp01(0.35 + rel * 0.4)
               : rel > 1.15 ? clamp01(1.15 - (rel - 1) * 0.8)
               : 1;
      add('trajectory', traj,
          'assessed at ' + (implied * 100).toFixed(0) + '% of its solid sale, town runs ' +
          (s.ratio * 100).toFixed(0) + '%');
    } else {
      add('trajectory', null, 'needs a solid sale on record; nominal deed transfers are excluded');
    }

    // R - Recourse, 10
    if (a && a.latest && a.latest.win_rate_filed != null) {
      add('recourse', clamp01((a.latest.win_rate_filed - 20) / 45),
          a.latest.win_rate_filed + '% of filed appeals reduced in ' + titleCase(a.county) + ' County');
    } else {
      add('recourse', null);
    }

    return Core.aggregate(detail);
  }

  function WD_VERDICT(score) { return Core.verdict(score); }

  function wdBadge(r, size) {
    var w = watchdogScore(r);
    if (!w) return '';
    var cls = 'wd-badge ' + w.band + (size ? ' ' + size : '');
    return '<span class="' + cls + '" data-score-model="' + w.modelVersion + '" title="Watchdog Score ' + w.score +
      ' of 100. ' + esc(w.verdict) + '. Powered by the ROBUST Framework.">' +
      '<i class="fas fa-dog"></i><b>' + w.score + '</b></span>';
  }

  function wdBreakdown(r) {
    var w = watchdogScore(r);
    if (!w) return '';
    return '<div class="wd-break" data-score-framework="' + w.frameworkVersion + '" data-score-model="' + w.modelVersion + '">' +
      '<div class="wd-conf"><b>ROBUST Framework</b> \u00b7 Recourse, Overassessment Position, Burden, Uniformity, Stability and Trajectory.</div>' +
      Core.ORDER.map(function (key) {
        var d = w.detail[key];
        if (!d) return '';
        var has = d.score != null;
        return '<div class="wd-r' + (has ? '' : ' off') + '">' +
          '<span class="wd-rl"><a href="/property/robust/' + d.slug + '/" style="color:inherit;text-decoration:none">' + d.label + '</a><em>' + (d.note || '') + '</em></span>' +
          '<span class="wd-rb"><i style="width:' + (has ? d.score : 0) + '%"></i></span>' +
          '<span class="wd-rn">' + (has ? d.score : '-') + '</span>' +
          '<span class="wd-rw">' + d.weight + '%</span>' +
        '</div>';
      }).join('') +
      '<div class="wd-conf">Built from ' + Math.round(w.covered * 100) + '% of the available weight, ' +
      w.confidence + ' confidence. Components with no data are dropped and the rest reweighted, rather than ' +
      'filled with a guess. <a href="/property/robust/" style="font-weight:800">How ROBUST works</a></div>' +
    '</div>';
  }

  function toolCard(title, icon, body) {
    return '<section class="sec"><h4><i class="fas ' + icon + '"></i>' + title + '</h4>' + body + '</section>';
  }

  Object.assign(window, { clamp01: clamp01, watchdogScore: watchdogScore, WD_VERDICT: WD_VERDICT, wdBadge: wdBadge, wdBreakdown: wdBreakdown, toolCard: toolCard, ROBUST_META: ROBUST_META });

  if (document.body && document.body.getAttribute('data-sidebar-page') === 'dashboard') {
    import('../dashboard-workspace.js').catch(function (error) {
      console.error('Modern dashboard dashboard could not load:', error);
    });
  }
})();
})();

