(function () {
  ['loadAbatements', 'loadExemptPilot'].forEach(function (fn) {
    try { if (typeof window[fn] === 'function') window.__wdHomeToolLoads.push(Promise.resolve(window[fn]())); } catch (_) {}
  });
  // Resolves once reference data has settled; a failed load never blocks a section.
  window.NJPropertyToolsReady = Promise.all(window.__wdHomeToolLoads.map(function (p) { return Promise.resolve(p).catch(function () {}); }));
})();
